let out = "";

for (let a = 1; a <= 3; a++) {
  for (let b = 1; b <= 3; b++) {
    if (b === a) continue;
    if (b > a) break;
    out += `${a}${b} `;
  }
}

console.log(out.trim());

let count = 0;

outer: for (let a = 0; a < 3; a++) {
  for (let b = 0; b < 3; b++) {
    if (b === 1) continue outer;
    if (a === 2) break outer;
    count++;
  }
}

console.log(count);
